import React, { useState, useEffect, useRef, useCallback } from 'react';
import { User } from '@supabase/supabase-js';
import { Sound, SoundType, Scene, AtmosphereLevel } from './types';
import { SoundManager } from './lib/SoundManager';
import { signInWithUsername, signOut, getUser } from './lib/authService';
import { 
    getSoundFiles, 
    uploadSoundFile, 
    updateSoundFile, 
    deleteSoundFile,
    getScenes,
    getSoundSceneJoins,
    addScene,
    removeScene,
    updateSceneJoins
} from './lib/soundFileService';
import { SoundTile } from './components/SoundTile';
import { SceneHeader } from './components/PresetHeader';
import { SoundManagerModal } from './components/SoundManagerModal';
import { SceneManagerModal } from './components/SceneManagerModal';
import { supabase } from './lib/supabase';
import { AtmosphereFooter } from './components/AtmosphereFooter';
import { SearchWidget } from './components/SearchWidget';

const App: React.FC = () => {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [authError, setAuthError] = useState<string | null>(null);

    const [sounds, setSounds] = useState<Sound[]>([]);
    const [librarySounds, setLibrarySounds] = useState<Sound[]>([]);
    const [scenes, setScenes] = useState<Scene[]>([]);
    const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
    const [activeMoodFilter, setActiveMoodFilter] = useState<string | null>(null);
    const [activeSETypeFilter, setActiveSETypeFilter] = useState<string | null>(null);
    const [activeAtmosphere, setActiveAtmosphere] = useState<AtmosphereLevel | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    const [playingStates, setPlayingStates] = useState<Record<string, boolean>>({});
    const [audioContextState, setAudioContextState] = useState<AudioContextState>('suspended');
    const [masterBGMVolume, setMasterBGMVolume] = useState(0.5);
    const soundManagerRef = useRef<SoundManager | null>(null);

    const [isSoundManagerModalOpen, setSoundManagerModalOpen] = useState(false);
    const [isSceneManagerModalOpen, setSceneManagerModalOpen] = useState(false);

    const fetchData = async (userId: string, showLoading = true) => {
        if (showLoading) setIsLoading(true);

        const { data: { user: currentUser } } = await supabase.auth.getUser();
        const favoriteSoundIds = new Set<string>(currentUser?.user_metadata?.favorite_sounds || []);

        const [fetchedSounds, fetchedScenes, fetchedJoins] = await Promise.all([
            getSoundFiles(userId),
            getScenes(userId),
            getSoundSceneJoins(userId),
        ]);

        const scenesById = new Map(fetchedScenes.map(s => [s.id, s.name]));
        const soundsWithScenes = fetchedSounds.map(sound => {
            const soundScenes = fetchedJoins
                .filter(j => j.sound_id === sound.id)
                .map(j => {
                    const sceneName = scenesById.get(j.scene_id);
                    return sceneName ? { id: j.scene_id, name: sceneName, atmosphere: j.atmosphere } as Scene : undefined;
                })
                .filter((s): s is Scene => s !== undefined);

            // Recover global atmosphere from joins.
            // Since we removed the 'atmosphere' column from sound_files, we derive it
            // for global sounds from the first available scene join (assuming uniformity)
            // or from any specific join if we are filtering by scene later.
            let derivedAtmosphere: AtmosphereLevel[] | null = null;

            // Try to find a representative atmosphere config
            const representativeJoin = fetchedJoins.find(j => j.sound_id === sound.id && j.atmosphere && j.atmosphere.length > 0);
            if (representativeJoin) {
                derivedAtmosphere = representativeJoin.atmosphere;
            }

            return { 
                ...sound, 
                scenes: soundScenes,
                atmosphere: derivedAtmosphere,
                favorite: favoriteSoundIds.has(sound.id) 
            };
        });

        setLibrarySounds(soundsWithScenes);
        setScenes(fetchedScenes.sort((a,b) => a.name.localeCompare(b.name)));
        soundManagerRef.current?.loadSounds(soundsWithScenes);

        if (showLoading) setIsLoading(false);
    };

    // Authentication and data fetching
    useEffect(() => {
        const checkUser = async () => {
            const currentUser = await getUser();
            setUser(currentUser);
            if (!currentUser) setIsLoading(false);
        };
        checkUser();

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user ?? null);
            if (!session?.user) setIsLoading(false);
        });

        return () => subscription.unsubscribe();
    }, []);

    const onStateChange = useCallback((newState: { playingStates: Record<string, boolean>, audioContextState: AudioContextState }) => {
        setPlayingStates(newState.playingStates);
        setAudioContextState(newState.audioContextState);
    }, []);

    useEffect(() => {
        if (user && !soundManagerRef.current) {
            soundManagerRef.current = new SoundManager(onStateChange);
        }
        if (user) {
            fetchData(user.id, true);
        } else {
            setSounds([]);
            setLibrarySounds([]);
            setScenes([]);
            setActiveSceneId(null);
            soundManagerRef.current?.stopAllSounds();
        }
    }, [user, onStateChange]);

    useEffect(() => {
        let filtered = librarySounds;

        // 1. Scene Filter
        if (activeSceneId !== null) {
            filtered = filtered.filter(sound => 
                sound.include_in_all_scenes || sound.scenes?.some(scene => scene.id === activeSceneId)
            );
        }

        // 2. Search Filter (Live typing)
        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            filtered = filtered.filter(s => 
                s.name.toLowerCase().includes(q) || 
                s.category_tag?.toLowerCase().includes(q) ||
                s.mood_tag?.toLowerCase().includes(q) ||
                s.location_tag?.toLowerCase().includes(q) ||
                s.type_tag?.toLowerCase().includes(q)
            );
        }

        setSounds(filtered);

        setActiveMoodFilter(null);
        setActiveSETypeFilter(null);

        // Removed auto-stop logic to allow continuous playback when switching scenes.

        setActiveAtmosphere(null); 
    }, [activeSceneId, librarySounds, searchQuery]); 

    const handleSceneChange = (id: string | null) => {
        setActiveSceneId(id);
        setSearchQuery(''); 
    }

    // Handlers
    const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const { username, password } = Object.fromEntries(new FormData(e.currentTarget));
        if (typeof username !== 'string' || typeof password !== 'string') return;

        const { error } = await signInWithUsername(username, password);
        if (error) setAuthError(error.message);
        else setAuthError(null);
    };

    const handleLogout = async () => {
        soundManagerRef.current?.stopAllSounds();
        await signOut();
    };

    const handlePlaySound = (sound: Sound) => {
        // If the user manually starts a BGM, we assume they want to switch context from the current atmosphere
        // and fade out any "Scene Atmosphere" sounds (BGM and Ambience) currently playing.
        if (sound.type === 'Background Music' && activeAtmosphere) {
             const playingIds = Object.keys(playingStates).filter(id => playingStates[id]);
             playingIds.forEach(id => {
                 const s = librarySounds.find(ls => ls.id === id);
                 if (s && (s.type === 'Ambience' || s.type === 'Background Music')) {
                     // Don't stop the sound we are about to play (SoundManager handles restart/debounce)
                     if (s.id !== sound.id) {
                         soundManagerRef.current?.stopSound(s);
                     }
                 }
             });
             setActiveAtmosphere(null);
        }
        soundManagerRef.current?.playSound(sound);
    };

    const handleStopSound = (sound: Sound) => soundManagerRef.current?.stopSound(sound);
    const handleToggleGlobalPlayPause = () => soundManagerRef.current?.toggleGlobalPlayPause();
    const handleStopAllSounds = () => {
        setActiveAtmosphere(null);
        soundManagerRef.current?.stopAllSounds();
    }

    const handleBGMVolumeChange = (volume: number) => {
        setMasterBGMVolume(volume);
        soundManagerRef.current?.setMasterBGMVolume(volume);
    };

    const handleSelectAtmosphere = (atmosphere: AtmosphereLevel) => {
        if (!soundManagerRef.current) return;

        const newAtmosphere = atmosphere === activeAtmosphere ? null : atmosphere;
        setActiveAtmosphere(newAtmosphere);

        // Use librarySounds to check ALL bgm/ambience, so we can stop sounds from previous scenes
        // that are no longer relevant to the new context.
        const contextSounds = librarySounds.filter(s => s.type === 'Background Music' || s.type === 'Ambience');

        contextSounds.forEach(sound => {
            const isPlaying = playingStates[sound.id];
            let matchesAtmosphere = false;

            if (newAtmosphere) {
                if (activeSceneId) {
                    const sceneInfo = sound.scenes?.find(s => s.id === activeSceneId);
                    if (sceneInfo && sceneInfo.atmosphere) {
                         matchesAtmosphere = sceneInfo.atmosphere.includes(newAtmosphere);
                    } else if (sound.include_in_all_scenes && sound.atmosphere) {
                         // Fallback to global derived atmosphere if available
                         matchesAtmosphere = sound.atmosphere.includes(newAtmosphere);
                    }
                } else {
                    // Global / All View
                    if (sound.atmosphere) {
                        matchesAtmosphere = sound.atmosphere.includes(newAtmosphere);
                    }
                }
            }

            const shouldBePlaying = newAtmosphere && matchesAtmosphere;

            if (isPlaying && !shouldBePlaying) {
                soundManagerRef.current?.stopSound(sound);
            } else if (!isPlaying && shouldBePlaying) {
                soundManagerRef.current?.playSound(sound);
            }
        });
    };

    // Scene Management Handlers
    const handleAddScene = async (name: string) => {
        if (!user) return;
        await addScene(user.id, name);
        await fetchData(user.id, false);
    }

    const handleRemoveScene = async (id: string) => {
        if (!user) return { success: false, error: "Not authenticated" };

        const result = await removeScene(id, user.id);

        if (result.success) {
            if (activeSceneId === id) setActiveSceneId(null);
            await fetchData(user.id, false);
        }
        return result;
    }

    const handleUpdateSceneJoins = async (sceneId: string, soundData: Array<{ sound_id: string; atmosphere: AtmosphereLevel[] }>) => {
        if (!user) return;
        await updateSceneJoins(sceneId, soundData);
        await fetchData(user.id, false);
    };

    const handleAddSound = async (file: File, details: Omit<Sound, 'id' | 'user_id' | 'file_path' | 'publicURL' | 'created_at' | 'scenes' | 'atmosphere' | 'favorite'> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null>, favorite: boolean }) => {
        if (!user) return;
        const { favorite, ...otherDetails } = details;
        const newSound = await uploadSoundFile(user.id, file, otherDetails);

        if (newSound) {
            if (favorite) {
                const { data: { user: currentUser } } = await supabase.auth.getUser();
                const currentFavorites: string[] = currentUser?.user_metadata?.favorite_sounds || [];
                const newFavorites = [...new Set([...currentFavorites, newSound.id])];
                await supabase.auth.updateUser({ data: { favorite_sounds: newFavorites } });
            }
            await fetchData(user.id, false);
        }
    };

    const handleUpdateSound = async (id: string, updates: Partial<Omit<Sound, 'scenes'>> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null> }) => {
        if (!user) return;

        const { favorite, ...otherUpdates } = updates;

        if (typeof favorite === 'boolean') {
            const { data: { user: currentUser } } = await supabase.auth.getUser();
            if (currentUser) {
                const currentFavorites: string[] = currentUser.user_metadata?.favorite_sounds || [];
                let newFavorites: string[];
                if (favorite) {
                    newFavorites = [...new Set([...currentFavorites, id])];
                } else {
                    newFavorites = currentFavorites.filter((favId: string) => favId !== id);
                }

                if (JSON.stringify(currentFavorites.sort()) !== JSON.stringify(newFavorites.sort())) {
                    await supabase.auth.updateUser({ data: { favorite_sounds: newFavorites } });
                }
            }
        }

        const hasOtherUpdates = Object.keys(otherUpdates).length > 0;

        if(hasOtherUpdates) {
             await updateSoundFile(id, otherUpdates as any);
        }

        await fetchData(user.id, false);
    };

    const handleDeleteSound = async (soundToDelete: Sound) => {
        if (!user) return;
        soundManagerRef.current?.stopSound(soundToDelete);
        const { success, error } = await deleteSoundFile(soundToDelete);
        if (success) {
            await fetchData(user.id, false);
        } else {
            console.error("Delete failed:", error);
            alert(`Failed to delete sound. ${error}`);
        }
    };

    if (isLoading) {
        return <div className="h-screen w-screen flex items-center justify-center bg-stone-900 text-white">Loading...</div>;
    }

    if (!user) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900 flex flex-col justify-center items-center p-4">
                <div className="w-full max-w-sm">
                    <img 
                        src="https://nielskrikke.com/wp-content/uploads/2025/12/sound-app-icon.png" 
                        alt="Logo" 
                        className="w-24 h-24 mx-auto mb-6 shadow-2xl rounded-2xl hover:scale-105 transition-transform duration-500 ease-out"
                    />
                    <h1 className="text-5xl font-medieval font-bold text-center text-white mb-8 drop-shadow-md">TTRPG Soundboard</h1>
                    <form onSubmit={handleLogin} className="bg-stone-900/60 backdrop-blur-2xl border border-stone-700/50 shadow-2xl rounded-3xl px-8 pt-6 pb-8 mb-4 animate-modal-in">
                        <div className="mb-4">
                            <label className="block text-stone-300 text-sm font-bold mb-2" htmlFor="username">Username</label>
                            <input className="shadow appearance-none border border-stone-600/50 rounded-xl w-full py-2 px-3 bg-stone-800/40 text-white leading-tight focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 transition-all" id="username" name="username" type="text" placeholder="Username" required />
                        </div>
                        <div className="mb-6">
                            <label className="block text-stone-300 text-sm font-bold mb-2" htmlFor="password">Password</label>
                            <input className="shadow appearance-none border border-stone-600/50 rounded-xl w-full py-2 px-3 bg-stone-800/40 text-white mb-3 leading-tight focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 transition-all" id="password" name="password" type="password" placeholder="******************" required />
                            {authError && <p className="text-red-400 text-xs italic bg-red-900/20 p-2 rounded border border-red-800/50">{authError}</p>}
                        </div>
                        <div className="flex items-center justify-between">
                            <button className="bg-amber-600 hover:bg-amber-500 text-white font-bold py-2 px-4 rounded-xl focus:outline-none focus:shadow-outline w-full shadow-lg hover:shadow-amber-900/20 transition-all hover:scale-105 active:scale-95 duration-300" type="submit">
                                Sign In / Sign Up
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        );
    }

    const renderSoundSection = (type: SoundType, title: string) => {
        let sectionSounds = sounds.filter(s => s.type === type);
        let filterUI = null;

        if (type === 'Background Music') {
            const moods = [...new Set(
                librarySounds
                    .filter(s => s.type === 'Background Music' && s.mood_tag)
                    .map(s => s.mood_tag!)
            )].sort();

            if (activeMoodFilter) {
                sectionSounds = sectionSounds.filter(s => s.mood_tag === activeMoodFilter);
            }

            if (moods.length > 0) {
                filterUI = (
                    <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm font-semibold text-stone-400">Mood:</span>
                         <button 
                            onClick={() => setActiveMoodFilter(null)} 
                            className={`px-3 py-1 text-xs rounded-full transition-colors ${!activeMoodFilter ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                        >
                            All
                        </button>
                        {moods.map(mood => (
                            <button 
                                key={mood} 
                                onClick={() => setActiveMoodFilter(mood)} 
                                className={`px-3 py-1 text-xs rounded-full transition-colors ${activeMoodFilter === mood ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                            >
                                {mood}
                            </button>
                        ))}
                    </div>
                );
            }
        } else if (type === 'One-shots') {
            const types = [...new Set(
                librarySounds
                    .filter(s => s.type === 'One-shots' && s.type_tag)
                    .flatMap(s => s.type_tag!.split(',').map(t => t.trim()).filter(Boolean))
            )].sort();

            if (activeSETypeFilter) {
                sectionSounds = sectionSounds.filter(s => 
                    s.type_tag?.split(',').map(t => t.trim()).includes(activeSETypeFilter)
                );
            }

            if (types.length > 0) {
                filterUI = (
                    <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm font-semibold text-stone-400">Type:</span>
                        <button
                            onClick={() => setActiveSETypeFilter(null)}
                            className={`px-3 py-1 text-xs rounded-full transition-colors ${!activeSETypeFilter ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                        >
                            All
                        </button>
                        {types.map(sfxType => (
                            <button
                                key={sfxType}
                                onClick={() => setActiveSETypeFilter(sfxType)}
                                className={`px-3 py-1 text-xs rounded-full transition-colors ${activeSETypeFilter === sfxType ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                            >
                                {sfxType}
                            </button>
                        ))}
                    </div>
                );
            }
        }

        const hasSoundsOfTypeInScene = sounds.some(s => s.type === type);

        if (!hasSoundsOfTypeInScene && !searchQuery) {
            return null;
        }

        if (searchQuery && sectionSounds.length === 0) {
            return null;
        }

        sectionSounds.sort((a, b) => {
            // 1. Favorites always first
            if (a.favorite !== b.favorite) {
                return a.favorite ? -1 : 1;
            }

            // 2. If we are in a Specific Scene view, prioritize scene-specific tiles (include_in_all_scenes = false)
            if (activeSceneId !== null) {
                if (a.include_in_all_scenes !== b.include_in_all_scenes) {
                    return a.include_in_all_scenes ? 1 : -1; // False comes before True
                }
            }

            // 3. Alphabetical
            return a.name.localeCompare(b.name);
        });

        return (
            <section className="mb-8">
                <h2 className="text-2xl font-medieval font-bold text-white mb-4">{title}</h2>
                {filterUI}
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-3 md:gap-4">
                    {sectionSounds.map(sound => (
                        <SoundTile 
                            key={sound.id} 
                            sound={sound}
                            isPlaying={!!playingStates[sound.id]}
                            onPlay={handlePlaySound}
                            onStop={handleStopSound}
                        />
                    ))}
                </div>
            </section>
        );
    }

    const isAnythingPlaying = Object.values(playingStates).some(p => p);
    const sortedLibrarySounds = [...librarySounds].sort((a, b) => a.name.localeCompare(b.name));

    return (
        <div className="min-h-screen bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900 flex flex-col">
            <SceneHeader
                scenes={scenes}
                activeSceneId={activeSceneId}
                onSelectScene={handleSceneChange}
                isAudioContextPlaying={audioContextState === 'running'}
                onToggleGlobalPlayPause={handleToggleGlobalPlayPause}
                onStopAllSounds={handleStopAllSounds}
                bgmVolume={masterBGMVolume}
                onBgmVolumeChange={handleBGMVolumeChange}
                onLogout={handleLogout}
                onOpenSoundManager={() => setSoundManagerModalOpen(true)}
                onOpenSceneManager={() => setSceneManagerModalOpen(true)}
                airplayElement={soundManagerRef.current?.airPlayAudioElement || null}
                isPlayerVisible={isAnythingPlaying}
            />

            <main className="flex-grow p-4 md:p-8 pb-24">
                {renderSoundSection('Background Music', 'Background Music')}
                {renderSoundSection('Ambience', 'Ambience')}
                {renderSoundSection('One-shots', 'One-shots')}

                 {sounds.length === 0 && librarySounds.length > 0 && (
                    <div className="text-center text-stone-400 mt-10">
                        {searchQuery ? (
                             <p className="text-lg">No sounds match "{searchQuery}"</p>
                        ) : (
                            <>
                                <p className="text-lg">No sounds found in this scene.</p>
                                <p>Try selecting another scene or "All".</p>
                            </>
                        )}
                    </div>
                 )}
            </main>

            <AtmosphereFooter 
                activeAtmosphere={activeAtmosphere}
                onSelectAtmosphere={handleSelectAtmosphere}
                isSceneActive={!!activeSceneId || activeSceneId === null} // Always active now
            />

            <SearchWidget searchQuery={searchQuery} setSearchQuery={setSearchQuery} />

            <SoundManagerModal
                isOpen={isSoundManagerModalOpen}
                onClose={() => setSoundManagerModalOpen(false)}
                sounds={sortedLibrarySounds}
                allScenes={scenes}
                onAddSound={handleAddSound}
                onUpdateSound={handleUpdateSound}
                onDeleteSound={handleDeleteSound}
            />
            <SceneManagerModal
                isOpen={isSceneManagerModalOpen}
                onClose={() => setSceneManagerModalOpen(false)}
                scenes={scenes}
                sounds={sortedLibrarySounds}
                onAddScene={handleAddScene}
                onRemoveScene={handleRemoveScene}
                onUpdateSceneJoins={handleUpdateSceneJoins}
            />
        </div>
    );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { User } from '@supabase/supabase-js';
import { Sound, SoundType, Scene, AtmosphereLevel } from './types';
import { SoundManager } from './lib/SoundManager';
import { signInWithUsername, signOut, getUser } from './lib/authService';
import { 
    getSoundFiles, 
    uploadSoundFile, 
    updateSoundFile, 
    deleteSoundFile,
    getScenes,
    getSoundSceneJoins,
    addScene,
    removeScene,
    updateSceneJoins
} from './lib/soundFileService';
import { SoundTile } from './components/SoundTile';
import { SceneHeader } from './components/PresetHeader';
import { SoundManagerModal } from './components/SoundManagerModal';
import { SceneManagerModal } from './components/SceneManagerModal';
import { supabase } from './lib/supabase';
import { AtmosphereFooter } from './components/AtmosphereFooter';
import { SearchWidget } from './components/SearchWidget';

const App: React.FC = () => {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [authError, setAuthError] = useState<string | null>(null);

    const [sounds, setSounds] = useState<Sound[]>([]);
    const [librarySounds, setLibrarySounds] = useState<Sound[]>([]);
    const [scenes, setScenes] = useState<Scene[]>([]);
    const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
    const [activeMoodFilter, setActiveMoodFilter] = useState<string | null>(null);
    const [activeSETypeFilter, setActiveSETypeFilter] = useState<string | null>(null);
    const [activeAtmosphere, setActiveAtmosphere] = useState<AtmosphereLevel | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    const [playingStates, setPlayingStates] = useState<Record<string, boolean>>({});
    const [audioContextState, setAudioContextState] = useState<AudioContextState>('suspended');
    const [masterBGMVolume, setMasterBGMVolume] = useState(0.5);
    const soundManagerRef = useRef<SoundManager | null>(null);

    const [isSoundManagerModalOpen, setSoundManagerModalOpen] = useState(false);
    const [isSceneManagerModalOpen, setSceneManagerModalOpen] = useState(false);

    const fetchData = async (userId: string, showLoading = true) => {
        if (showLoading) setIsLoading(true);

        const { data: { user: currentUser } } = await supabase.auth.getUser();
        const favoriteSoundIds = new Set<string>(currentUser?.user_metadata?.favorite_sounds || []);

        const [fetchedSounds, fetchedScenes, fetchedJoins] = await Promise.all([
            getSoundFiles(userId),
            getScenes(userId),
            getSoundSceneJoins(userId),
        ]);

        const scenesById = new Map(fetchedScenes.map(s => [s.id, s.name]));
        const soundsWithScenes = fetchedSounds.map(sound => {
            const soundScenes = fetchedJoins
                .filter(j => j.sound_id === sound.id)
                .map(j => {
                    const sceneName = scenesById.get(j.scene_id);
                    return sceneName ? { id: j.scene_id, name: sceneName, atmosphere: j.atmosphere } as Scene : undefined;
                })
                .filter((s): s is Scene => s !== undefined);

            // Recover global atmosphere from joins.
            // Since we removed the 'atmosphere' column from sound_files, we derive it
            // for global sounds from the first available scene join (assuming uniformity)
            // or from any specific join if we are filtering by scene later.
            let derivedAtmosphere: AtmosphereLevel[] | null = null;

            // Try to find a representative atmosphere config
            const representativeJoin = fetchedJoins.find(j => j.sound_id === sound.id && j.atmosphere && j.atmosphere.length > 0);
            if (representativeJoin) {
                derivedAtmosphere = representativeJoin.atmosphere;
            }

            return { 
                ...sound, 
                scenes: soundScenes,
                atmosphere: derivedAtmosphere,
                favorite: favoriteSoundIds.has(sound.id) 
            };
        });

        setLibrarySounds(soundsWithScenes);
        setScenes(fetchedScenes.sort((a,b) => a.name.localeCompare(b.name)));
        soundManagerRef.current?.loadSounds(soundsWithScenes);

        if (showLoading) setIsLoading(false);
    };

    // Authentication and data fetching
    useEffect(() => {
        const checkUser = async () => {
            const currentUser = await getUser();
            setUser(currentUser);
            if (!currentUser) setIsLoading(false);
        };
        checkUser();

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user ?? null);
            if (!session?.user) setIsLoading(false);
        });

        return () => subscription.unsubscribe();
    }, []);

    const onStateChange = useCallback((newState: { playingStates: Record<string, boolean>, audioContextState: AudioContextState }) => {
        setPlayingStates(newState.playingStates);
        setAudioContextState(newState.audioContextState);
    }, []);

    useEffect(() => {
        if (user && !soundManagerRef.current) {
            soundManagerRef.current = new SoundManager(onStateChange);
        }
        if (user) {
            fetchData(user.id, true);
        } else {
            setSounds([]);
            setLibrarySounds([]);
            setScenes([]);
            setActiveSceneId(null);
            soundManagerRef.current?.stopAllSounds();
        }
    }, [user, onStateChange]);

    useEffect(() => {
        let filtered = librarySounds;

        // 1. Scene Filter
        if (activeSceneId !== null) {
            filtered = filtered.filter(sound => 
                sound.include_in_all_scenes || sound.scenes?.some(scene => scene.id === activeSceneId)
            );
        }

        // 2. Search Filter (Live typing)
        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            filtered = filtered.filter(s => 
                s.name.toLowerCase().includes(q) || 
                s.category_tag?.toLowerCase().includes(q) ||
                s.mood_tag?.toLowerCase().includes(q) ||
                s.location_tag?.toLowerCase().includes(q) ||
                s.type_tag?.toLowerCase().includes(q)
            );
        }

        setSounds(filtered);

        setActiveMoodFilter(null);
        setActiveSETypeFilter(null);

        // Removed auto-stop logic to allow continuous playback when switching scenes.

        setActiveAtmosphere(null); 
    }, [activeSceneId, librarySounds, searchQuery]); 

    const handleSceneChange = (id: string | null) => {
        setActiveSceneId(id);
        setSearchQuery(''); 
    }

    // Handlers
    const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const { username, password } = Object.fromEntries(new FormData(e.currentTarget));
        if (typeof username !== 'string' || typeof password !== 'string') return;

        const { error } = await signInWithUsername(username, password);
        if (error) setAuthError(error.message);
        else setAuthError(null);
    };

    const handleLogout = async () => {
        soundManagerRef.current?.stopAllSounds();
        await signOut();
    };

    const handlePlaySound = (sound: Sound) => {
        // If the user manually starts a BGM, we assume they want to switch context from the current atmosphere
        // and fade out any "Scene Atmosphere" sounds (BGM and Ambience) currently playing.
        if (sound.type === 'Background Music' && activeAtmosphere) {
             const playingIds = Object.keys(playingStates).filter(id => playingStates[id]);
             playingIds.forEach(id => {
                 const s = librarySounds.find(ls => ls.id === id);
                 if (s && (s.type === 'Ambience' || s.type === 'Background Music')) {
                     // Don't stop the sound we are about to play (SoundManager handles restart/debounce)
                     if (s.id !== sound.id) {
                         soundManagerRef.current?.stopSound(s);
                     }
                 }
             });
             setActiveAtmosphere(null);
        }
        soundManagerRef.current?.playSound(sound);
    };

    const handleStopSound = (sound: Sound) => soundManagerRef.current?.stopSound(sound);
    const handleToggleGlobalPlayPause = () => soundManagerRef.current?.toggleGlobalPlayPause();
    const handleStopAllSounds = () => {
        setActiveAtmosphere(null);
        soundManagerRef.current?.stopAllSounds();
    }

    const handleBGMVolumeChange = (volume: number) => {
        setMasterBGMVolume(volume);
        soundManagerRef.current?.setMasterBGMVolume(volume);
    };

    const handleSelectAtmosphere = (atmosphere: AtmosphereLevel) => {
        if (!soundManagerRef.current) return;

        const newAtmosphere = atmosphere === activeAtmosphere ? null : atmosphere;
        setActiveAtmosphere(newAtmosphere);

        // Use librarySounds to check ALL bgm/ambience, so we can stop sounds from previous scenes
        // that are no longer relevant to the new context.
        const contextSounds = librarySounds.filter(s => s.type === 'Background Music' || s.type === 'Ambience');

        contextSounds.forEach(sound => {
            const isPlaying = playingStates[sound.id];
            let matchesAtmosphere = false;

            if (newAtmosphere) {
                if (activeSceneId) {
                    const sceneInfo = sound.scenes?.find(s => s.id === activeSceneId);
                    if (sceneInfo && sceneInfo.atmosphere) {
                         matchesAtmosphere = sceneInfo.atmosphere.includes(newAtmosphere);
                    } else if (sound.include_in_all_scenes && sound.atmosphere) {
                         // Fallback to global derived atmosphere if available
                         matchesAtmosphere = sound.atmosphere.includes(newAtmosphere);
                    }
                } else {
                    // Global / All View
                    if (sound.atmosphere) {
                        matchesAtmosphere = sound.atmosphere.includes(newAtmosphere);
                    }
                }
            }

            const shouldBePlaying = newAtmosphere && matchesAtmosphere;

            if (isPlaying && !shouldBePlaying) {
                soundManagerRef.current?.stopSound(sound);
            } else if (!isPlaying && shouldBePlaying) {
                soundManagerRef.current?.playSound(sound);
            }
        });
    };

    // Scene Management Handlers
    const handleAddScene = async (name: string) => {
        if (!user) return;
        await addScene(user.id, name);
        await fetchData(user.id, false);
    }

    const handleRemoveScene = async (id: string) => {
        if (!user) return { success: false, error: "Not authenticated" };

        const result = await removeScene(id, user.id);

        if (result.success) {
            if (activeSceneId === id) setActiveSceneId(null);
            await fetchData(user.id, false);
        }
        return result;
    }

    const handleUpdateSceneJoins = async (sceneId: string, soundData: Array<{ sound_id: string; atmosphere: AtmosphereLevel[] }>) => {
        if (!user) return;
        await updateSceneJoins(sceneId, soundData);
        await fetchData(user.id, false);
    };

    const handleAddSound = async (file: File, details: Omit<Sound, 'id' | 'user_id' | 'file_path' | 'publicURL' | 'created_at' | 'scenes' | 'atmosphere' | 'favorite'> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null>, favorite: boolean }) => {
        if (!user) return;
        const { favorite, ...otherDetails } = details;
        const newSound = await uploadSoundFile(user.id, file, otherDetails);

        if (newSound) {
            if (favorite) {
                const { data: { user: currentUser } } = await supabase.auth.getUser();
                const currentFavorites: string[] = currentUser?.user_metadata?.favorite_sounds || [];
                const newFavorites = [...new Set([...currentFavorites, newSound.id])];
                await supabase.auth.updateUser({ data: { favorite_sounds: newFavorites } });
            }
            await fetchData(user.id, false);
        }
    };

    const handleUpdateSound = async (id: string, updates: Partial<Omit<Sound, 'scenes'>> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null> }) => {
        if (!user) return;

        const { favorite, ...otherUpdates } = updates;

        if (typeof favorite === 'boolean') {
            const { data: { user: currentUser } } = await supabase.auth.getUser();
            if (currentUser) {
                const currentFavorites: string[] = currentUser.user_metadata?.favorite_sounds || [];
                let newFavorites: string[];
                if (favorite) {
                    newFavorites = [...new Set([...currentFavorites, id])];
                } else {
                    newFavorites = currentFavorites.filter((favId: string) => favId !== id);
                }

                if (JSON.stringify(currentFavorites.sort()) !== JSON.stringify(newFavorites.sort())) {
                    await supabase.auth.updateUser({ data: { favorite_sounds: newFavorites } });
                }
            }
        }

        const hasOtherUpdates = Object.keys(otherUpdates).length > 0;

        if(hasOtherUpdates) {
             await updateSoundFile(id, otherUpdates as any);
        }

        await fetchData(user.id, false);
    };

    const handleDeleteSound = async (soundToDelete: Sound) => {
        if (!user) return;
        soundManagerRef.current?.stopSound(soundToDelete);
        const { success, error } = await deleteSoundFile(soundToDelete);
        if (success) {
            await fetchData(user.id, false);
        } else {
            console.error("Delete failed:", error);
            alert(`Failed to delete sound. ${error}`);
        }
    };

    if (isLoading) {
        return <div className="h-screen w-screen flex items-center justify-center bg-stone-900 text-white">Loading...</div>;
    }

    if (!user) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900 flex flex-col justify-center items-center p-4">
                <div className="w-full max-w-sm">
                    <img 
                        src="https://nielskrikke.com/wp-content/uploads/2025/12/sound-app-icon-v2.png" 
                        alt="Logo" 
                        className="w-24 h-24 mx-auto mb-6 shadow-2xl rounded-2xl hover:scale-105 transition-transform duration-500 ease-out"
                    />
                    <h1 className="text-5xl font-medieval font-bold text-center text-white mb-8 drop-shadow-md">TTRPG Soundboard</h1>
                    <form onSubmit={handleLogin} className="bg-stone-900/60 backdrop-blur-2xl border border-stone-700/50 shadow-2xl rounded-3xl px-8 pt-6 pb-8 mb-4 animate-modal-in">
                        <div className="mb-4">
                            <label className="block text-stone-300 text-sm font-bold mb-2" htmlFor="username">Username</label>
                            <input className="shadow appearance-none border border-stone-600/50 rounded-xl w-full py-2 px-3 bg-stone-800/40 text-white leading-tight focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 transition-all" id="username" name="username" type="text" placeholder="Username" required />
                        </div>
                        <div className="mb-6">
                            <label className="block text-stone-300 text-sm font-bold mb-2" htmlFor="password">Password</label>
                            <input className="shadow appearance-none border border-stone-600/50 rounded-xl w-full py-2 px-3 bg-stone-800/40 text-white mb-3 leading-tight focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 transition-all" id="password" name="password" type="password" placeholder="******************" required />
                            {authError && <p className="text-red-400 text-xs italic bg-red-900/20 p-2 rounded border border-red-800/50">{authError}</p>}
                        </div>
                        <div className="flex items-center justify-between">
                            <button className="bg-amber-600 hover:bg-amber-500 text-white font-bold py-2 px-4 rounded-xl focus:outline-none focus:shadow-outline w-full shadow-lg hover:shadow-amber-900/20 transition-all hover:scale-105 active:scale-95 duration-300" type="submit">
                                Sign In / Sign Up
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        );
    }

    const renderSoundSection = (type: SoundType, title: string) => {
        let sectionSounds = sounds.filter(s => s.type === type);
        let filterUI = null;

        if (type === 'Background Music') {
            const moods = [...new Set(
                librarySounds
                    .filter(s => s.type === 'Background Music' && s.mood_tag)
                    .map(s => s.mood_tag!)
            )].sort();

            if (activeMoodFilter) {
                sectionSounds = sectionSounds.filter(s => s.mood_tag === activeMoodFilter);
            }

            if (moods.length > 0) {
                filterUI = (
                    <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm font-semibold text-stone-400">Mood:</span>
                         <button 
                            onClick={() => setActiveMoodFilter(null)} 
                            className={`px-3 py-1 text-xs rounded-full transition-colors ${!activeMoodFilter ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                        >
                            All
                        </button>
                        {moods.map(mood => (
                            <button 
                                key={mood} 
                                onClick={() => setActiveMoodFilter(mood)} 
                                className={`px-3 py-1 text-xs rounded-full transition-colors ${activeMoodFilter === mood ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                            >
                                {mood}
                            </button>
                        ))}
                    </div>
                );
            }
        } else if (type === 'One-shots') {
            const types = [...new Set(
                librarySounds
                    .filter(s => s.type === 'One-shots' && s.type_tag)
                    .flatMap(s => s.type_tag!.split(',').map(t => t.trim()).filter(Boolean))
            )].sort();

            if (activeSETypeFilter) {
                sectionSounds = sectionSounds.filter(s => 
                    s.type_tag?.split(',').map(t => t.trim()).includes(activeSETypeFilter)
                );
            }

            if (types.length > 0) {
                filterUI = (
                    <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm font-semibold text-stone-400">Type:</span>
                        <button
                            onClick={() => setActiveSETypeFilter(null)}
                            className={`px-3 py-1 text-xs rounded-full transition-colors ${!activeSETypeFilter ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                        >
                            All
                        </button>
                        {types.map(sfxType => (
                            <button
                                key={sfxType}
                                onClick={() => setActiveSETypeFilter(sfxType)}
                                className={`px-3 py-1 text-xs rounded-full transition-colors ${activeSETypeFilter === sfxType ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                            >
                                {sfxType}
                            </button>
                        ))}
                    </div>
                );
            }
        }

        const hasSoundsOfTypeInScene = sounds.some(s => s.type === type);

        if (!hasSoundsOfTypeInScene && !searchQuery) {
            return null;
        }

        if (searchQuery && sectionSounds.length === 0) {
            return null;
        }

        sectionSounds.sort((a, b) => {
            // 1. Favorites always first
            if (a.favorite !== b.favorite) {
                return a.favorite ? -1 : 1;
            }

            // 2. If we are in a Specific Scene view, prioritize scene-specific tiles (include_in_all_scenes = false)
            if (activeSceneId !== null) {
                if (a.include_in_all_scenes !== b.include_in_all_scenes) {
                    return a.include_in_all_scenes ? 1 : -1; // False comes before True
                }
            }

            // 3. Alphabetical
            return a.name.localeCompare(b.name);
        });

        return (
            <section className="mb-8">
                <h2 className="text-2xl font-medieval font-bold text-white mb-4">{title}</h2>
                {filterUI}
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-3 md:gap-4">
                    {sectionSounds.map(sound => (
                        <SoundTile 
                            key={sound.id} 
                            sound={sound}
                            isPlaying={!!playingStates[sound.id]}
                            onPlay={handlePlaySound}
                            onStop={handleStopSound}
                        />
                    ))}
                </div>
            </section>
        );
    }

    const isAnythingPlaying = Object.values(playingStates).some(p => p);
    const sortedLibrarySounds = [...librarySounds].sort((a, b) => a.name.localeCompare(b.name));

    return (
        <div className="min-h-screen bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900 flex flex-col">
            <SceneHeader
                scenes={scenes}
                activeSceneId={activeSceneId}
                onSelectScene={handleSceneChange}
                isAudioContextPlaying={audioContextState === 'running'}
                onToggleGlobalPlayPause={handleToggleGlobalPlayPause}
                onStopAllSounds={handleStopAllSounds}
                bgmVolume={masterBGMVolume}
                onBgmVolumeChange={handleBGMVolumeChange}
                onLogout={handleLogout}
                onOpenSoundManager={() => setSoundManagerModalOpen(true)}
                onOpenSceneManager={() => setSceneManagerModalOpen(true)}
                airplayElement={soundManagerRef.current?.airPlayAudioElement || null}
                isPlayerVisible={isAnythingPlaying}
            />

            <main className="flex-grow p-4 md:p-8 pb-24">
                {renderSoundSection('Background Music', 'Background Music')}
                {renderSoundSection('Ambience', 'Ambience')}
                {renderSoundSection('One-shots', 'One-shots')}

                 {sounds.length === 0 && librarySounds.length > 0 && (
                    <div className="text-center text-stone-400 mt-10">
                        {searchQuery ? (
                             <p className="text-lg">No sounds match "{searchQuery}"</p>
                        ) : (
                            <>
                                <p className="text-lg">No sounds found in this scene.</p>
                                <p>Try selecting another scene or "All".</p>
                            </>
                        )}
                    </div>
                 )}
            </main>

            <AtmosphereFooter 
                activeAtmosphere={activeAtmosphere}
                onSelectAtmosphere={handleSelectAtmosphere}
                isSceneActive={!!activeSceneId || activeSceneId === null} // Always active now
            />

            <SearchWidget searchQuery={searchQuery} setSearchQuery={setSearchQuery} />

            <SoundManagerModal
                isOpen={isSoundManagerModalOpen}
                onClose={() => setSoundManagerModalOpen(false)}
                sounds={sortedLibrarySounds}
                allScenes={scenes}
                onAddSound={handleAddSound}
                onUpdateSound={handleUpdateSound}
                onDeleteSound={handleDeleteSound}
            />
            <SceneManagerModal
                isOpen={isSceneManagerModalOpen}
                onClose={() => setSceneManagerModalOpen(false)}
                scenes={scenes}
                sounds={sortedLibrarySounds}
                onAddScene={handleAddScene}
                onRemoveScene={handleRemoveScene}
                onUpdateSceneJoins={handleUpdateSceneJoins}
            />
        </div>
    );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { User } from '@supabase/supabase-js';
import { Sound, SoundType, Scene, AtmosphereLevel } from './types';
import { SoundManager } from './lib/SoundManager';
import { signInWithUsername, signOut, getUser } from './lib/authService';
import { 
    getSoundFiles, 
    uploadSoundFile, 
    updateSoundFile, 
    deleteSoundFile,
    getScenes,
    getSoundSceneJoins,
    addScene,
    removeScene,
    updateSceneJoins
} from './lib/soundFileService';
import { SoundTile } from './components/SoundTile';
import { SceneHeader } from './components/PresetHeader';
import { SoundManagerModal } from './components/SoundManagerModal';
import { SceneManagerModal } from './components/SceneManagerModal';
import { supabase } from './lib/supabase';
import { AtmosphereFooter } from './components/AtmosphereFooter';
import { SearchWidget } from './components/SearchWidget';

const App: React.FC = () => {
    const [user, setUser] = useState<User | null>(null);
    const [isLoading, setIsLoading] = useState(true);
    const [authError, setAuthError] = useState<string | null>(null);

    const [sounds, setSounds] = useState<Sound[]>([]);
    const [librarySounds, setLibrarySounds] = useState<Sound[]>([]);
    const [scenes, setScenes] = useState<Scene[]>([]);
    const [activeSceneId, setActiveSceneId] = useState<string | null>(null);
    const [activeMoodFilter, setActiveMoodFilter] = useState<string | null>(null);
    const [activeSETypeFilter, setActiveSETypeFilter] = useState<string | null>(null);
    const [activeAtmosphere, setActiveAtmosphere] = useState<AtmosphereLevel | null>(null);
    const [searchQuery, setSearchQuery] = useState('');

    const [playingStates, setPlayingStates] = useState<Record<string, boolean>>({});
    const [audioContextState, setAudioContextState] = useState<AudioContextState>('suspended');
    const [masterBGMVolume, setMasterBGMVolume] = useState(0.5);
    const soundManagerRef = useRef<SoundManager | null>(null);

    const [isSoundManagerModalOpen, setSoundManagerModalOpen] = useState(false);
    const [isSceneManagerModalOpen, setSceneManagerModalOpen] = useState(false);

    const fetchData = async (userId: string, showLoading = true) => {
        if (showLoading) setIsLoading(true);

        const { data: { user: currentUser } } = await supabase.auth.getUser();
        const favoriteSoundIds = new Set<string>(currentUser?.user_metadata?.favorite_sounds || []);

        const [fetchedSounds, fetchedScenes, fetchedJoins] = await Promise.all([
            getSoundFiles(userId),
            getScenes(userId),
            getSoundSceneJoins(userId),
        ]);

        const scenesById = new Map(fetchedScenes.map(s => [s.id, s.name]));
        const soundsWithScenes = fetchedSounds.map(sound => {
            const soundScenes = fetchedJoins
                .filter(j => j.sound_id === sound.id)
                .map(j => {
                    const sceneName = scenesById.get(j.scene_id);
                    return sceneName ? { id: j.scene_id, name: sceneName, atmosphere: j.atmosphere } as Scene : undefined;
                })
                .filter((s): s is Scene => s !== undefined);

            // Recover global atmosphere from joins.
            // Since we removed the 'atmosphere' column from sound_files, we derive it
            // for global sounds from the first available scene join (assuming uniformity)
            // or from any specific join if we are filtering by scene later.
            let derivedAtmosphere: AtmosphereLevel[] | null = null;

            // Try to find a representative atmosphere config
            const representativeJoin = fetchedJoins.find(j => j.sound_id === sound.id && j.atmosphere && j.atmosphere.length > 0);
            if (representativeJoin) {
                derivedAtmosphere = representativeJoin.atmosphere;
            }

            return { 
                ...sound, 
                scenes: soundScenes,
                atmosphere: derivedAtmosphere,
                favorite: favoriteSoundIds.has(sound.id) 
            };
        });

        setLibrarySounds(soundsWithScenes);
        setScenes(fetchedScenes.sort((a,b) => a.name.localeCompare(b.name)));
        soundManagerRef.current?.loadSounds(soundsWithScenes);

        if (showLoading) setIsLoading(false);
    };

    // Authentication and data fetching
    useEffect(() => {
        const checkUser = async () => {
            const currentUser = await getUser();
            setUser(currentUser);
            if (!currentUser) setIsLoading(false);
        };
        checkUser();

        const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
            setUser(session?.user ?? null);
            if (!session?.user) setIsLoading(false);
        });

        return () => subscription.unsubscribe();
    }, []);

    const onStateChange = useCallback((newState: { playingStates: Record<string, boolean>, audioContextState: AudioContextState }) => {
        setPlayingStates(newState.playingStates);
        setAudioContextState(newState.audioContextState);
    }, []);

    useEffect(() => {
        if (user && !soundManagerRef.current) {
            soundManagerRef.current = new SoundManager(onStateChange);
        }
        if (user) {
            fetchData(user.id, true);
        } else {
            setSounds([]);
            setLibrarySounds([]);
            setScenes([]);
            setActiveSceneId(null);
            soundManagerRef.current?.stopAllSounds();
        }
    }, [user, onStateChange]);

    useEffect(() => {
        let filtered = librarySounds;

        // 1. Scene Filter
        if (activeSceneId !== null) {
            filtered = filtered.filter(sound => 
                sound.include_in_all_scenes || sound.scenes?.some(scene => scene.id === activeSceneId)
            );
        }

        // 2. Search Filter (Live typing)
        if (searchQuery.trim()) {
            const q = searchQuery.toLowerCase();
            filtered = filtered.filter(s => 
                s.name.toLowerCase().includes(q) || 
                s.category_tag?.toLowerCase().includes(q) ||
                s.mood_tag?.toLowerCase().includes(q) ||
                s.location_tag?.toLowerCase().includes(q) ||
                s.type_tag?.toLowerCase().includes(q)
            );
        }

        setSounds(filtered);

        setActiveMoodFilter(null);
        setActiveSETypeFilter(null);

        // Removed auto-stop logic to allow continuous playback when switching scenes.

        setActiveAtmosphere(null); 
    }, [activeSceneId, librarySounds, searchQuery]); 

    const handleSceneChange = (id: string | null) => {
        setActiveSceneId(id);
        setSearchQuery(''); 
    }

    // Handlers
    const handleLogin = async (e: React.FormEvent<HTMLFormElement>) => {
        e.preventDefault();
        const { username, password } = Object.fromEntries(new FormData(e.currentTarget));
        if (typeof username !== 'string' || typeof password !== 'string') return;

        const { error } = await signInWithUsername(username, password);
        if (error) setAuthError(error.message);
        else setAuthError(null);
    };

    const handleLogout = async () => {
        soundManagerRef.current?.stopAllSounds();
        await signOut();
    };

    const handlePlaySound = (sound: Sound) => {
        // If the user manually starts a BGM, we assume they want to switch context from the current atmosphere
        // and fade out any "Scene Atmosphere" sounds (BGM and Ambience) currently playing.
        if (sound.type === 'Background Music' && activeAtmosphere) {
             const playingIds = Object.keys(playingStates).filter(id => playingStates[id]);
             playingIds.forEach(id => {
                 const s = librarySounds.find(ls => ls.id === id);
                 if (s && (s.type === 'Ambience' || s.type === 'Background Music')) {
                     // Don't stop the sound we are about to play (SoundManager handles restart/debounce)
                     if (s.id !== sound.id) {
                         soundManagerRef.current?.stopSound(s);
                     }
                 }
             });
             setActiveAtmosphere(null);
        }
        soundManagerRef.current?.playSound(sound);
    };

    const handleStopSound = (sound: Sound) => soundManagerRef.current?.stopSound(sound);
    const handleToggleGlobalPlayPause = () => soundManagerRef.current?.toggleGlobalPlayPause();
    const handleStopAllSounds = () => {
        setActiveAtmosphere(null);
        soundManagerRef.current?.stopAllSounds();
    }

    const handleBGMVolumeChange = (volume: number) => {
        setMasterBGMVolume(volume);
        soundManagerRef.current?.setMasterBGMVolume(volume);
    };

    const handleSelectAtmosphere = (atmosphere: AtmosphereLevel) => {
        if (!soundManagerRef.current) return;

        const newAtmosphere = atmosphere === activeAtmosphere ? null : atmosphere;
        setActiveAtmosphere(newAtmosphere);

        // Use librarySounds to check ALL bgm/ambience, so we can stop sounds from previous scenes
        // that are no longer relevant to the new context.
        const contextSounds = librarySounds.filter(s => s.type === 'Background Music' || s.type === 'Ambience');

        contextSounds.forEach(sound => {
            const isPlaying = playingStates[sound.id];
            let matchesAtmosphere = false;

            if (newAtmosphere) {
                if (activeSceneId) {
                    const sceneInfo = sound.scenes?.find(s => s.id === activeSceneId);
                    if (sceneInfo && sceneInfo.atmosphere) {
                         matchesAtmosphere = sceneInfo.atmosphere.includes(newAtmosphere);
                    } else if (sound.include_in_all_scenes && sound.atmosphere) {
                         // Fallback to global derived atmosphere if available
                         matchesAtmosphere = sound.atmosphere.includes(newAtmosphere);
                    }
                } else {
                    // Global / All View
                    if (sound.atmosphere) {
                        matchesAtmosphere = sound.atmosphere.includes(newAtmosphere);
                    }
                }
            }

            const shouldBePlaying = newAtmosphere && matchesAtmosphere;

            if (isPlaying && !shouldBePlaying) {
                soundManagerRef.current?.stopSound(sound);
            } else if (!isPlaying && shouldBePlaying) {
                soundManagerRef.current?.playSound(sound);
            }
        });
    };

    // Scene Management Handlers
    const handleAddScene = async (name: string) => {
        if (!user) return;
        await addScene(user.id, name);
        await fetchData(user.id, false);
    }

    const handleRemoveScene = async (id: string) => {
        if (!user) return { success: false, error: "Not authenticated" };

        const result = await removeScene(id, user.id);

        if (result.success) {
            if (activeSceneId === id) setActiveSceneId(null);
            await fetchData(user.id, false);
        }
        return result;
    }

    const handleUpdateSceneJoins = async (sceneId: string, soundData: Array<{ sound_id: string; atmosphere: AtmosphereLevel[] }>) => {
        if (!user) return;
        await updateSceneJoins(sceneId, soundData);
        await fetchData(user.id, false);
    };

    const handleAddSound = async (file: File, details: Omit<Sound, 'id' | 'user_id' | 'file_path' | 'publicURL' | 'created_at' | 'scenes' | 'atmosphere' | 'favorite'> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null>, favorite: boolean }) => {
        if (!user) return;
        const { favorite, ...otherDetails } = details;
        const newSound = await uploadSoundFile(user.id, file, otherDetails);

        if (newSound) {
            if (favorite) {
                const { data: { user: currentUser } } = await supabase.auth.getUser();
                const currentFavorites: string[] = currentUser?.user_metadata?.favorite_sounds || [];
                const newFavorites = [...new Set([...currentFavorites, newSound.id])];
                await supabase.auth.updateUser({ data: { favorite_sounds: newFavorites } });
            }
            await fetchData(user.id, false);
        }
    };

    const handleUpdateSound = async (id: string, updates: Partial<Omit<Sound, 'scenes'>> & { sceneIds: string[], sceneAtmospheres: Record<string, AtmosphereLevel[] | null> }) => {
        if (!user) return;

        const { favorite, ...otherUpdates } = updates;

        if (typeof favorite === 'boolean') {
            const { data: { user: currentUser } } = await supabase.auth.getUser();
            if (currentUser) {
                const currentFavorites: string[] = currentUser.user_metadata?.favorite_sounds || [];
                let newFavorites: string[];
                if (favorite) {
                    newFavorites = [...new Set([...currentFavorites, id])];
                } else {
                    newFavorites = currentFavorites.filter((favId: string) => favId !== id);
                }

                if (JSON.stringify(currentFavorites.sort()) !== JSON.stringify(newFavorites.sort())) {
                    await supabase.auth.updateUser({ data: { favorite_sounds: newFavorites } });
                }
            }
        }

        const hasOtherUpdates = Object.keys(otherUpdates).length > 0;

        if(hasOtherUpdates) {
             await updateSoundFile(id, otherUpdates as any);
        }

        await fetchData(user.id, false);
    };

    const handleDeleteSound = async (soundToDelete: Sound) => {
        if (!user) return;
        soundManagerRef.current?.stopSound(soundToDelete);
        const { success, error } = await deleteSoundFile(soundToDelete);
        if (success) {
            await fetchData(user.id, false);
        } else {
            console.error("Delete failed:", error);
            alert(`Failed to delete sound. ${error}`);
        }
    };

    if (isLoading) {
        return <div className="h-screen w-screen flex items-center justify-center bg-stone-900 text-white">Loading...</div>;
    }

    if (!user) {
        return (
            <div className="min-h-screen bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900 flex flex-col justify-center items-center p-4">
                <div className="w-full max-w-sm">
                    <img 
                        src="https://nielskrikke.com/wp-content/uploads/2025/12/sound-app-icon-v2.png" 
                        alt="Logo" 
                        className="w-24 h-24 mx-auto mb-6 shadow-2xl rounded-2xl hover:scale-105 transition-transform duration-500 ease-out"
                    />
                    <h1 className="text-5xl font-medieval font-bold text-center text-white mb-8 drop-shadow-md">Sound Forge</h1>
                    <form onSubmit={handleLogin} className="bg-stone-900/60 backdrop-blur-2xl border border-stone-700/50 shadow-2xl rounded-3xl px-8 pt-6 pb-8 mb-4 animate-modal-in">
                        <div className="mb-4">
                            <label className="block text-stone-300 text-sm font-bold mb-2" htmlFor="username">Username</label>
                            <input className="shadow appearance-none border border-stone-600/50 rounded-xl w-full py-2 px-3 bg-stone-800/40 text-white leading-tight focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 transition-all" id="username" name="username" type="text" placeholder="Username" required />
                        </div>
                        <div className="mb-6">
                            <label className="block text-stone-300 text-sm font-bold mb-2" htmlFor="password">Password</label>
                            <input className="shadow appearance-none border border-stone-600/50 rounded-xl w-full py-2 px-3 bg-stone-800/40 text-white mb-3 leading-tight focus:outline-none focus:border-amber-500 focus:ring-1 focus:ring-amber-500 transition-all" id="password" name="password" type="password" placeholder="******************" required />
                            {authError && <p className="text-red-400 text-xs italic bg-red-900/20 p-2 rounded border border-red-800/50">{authError}</p>}
                        </div>
                        <div className="flex items-center justify-between">
                            <button className="bg-amber-600 hover:bg-amber-500 text-white font-bold py-2 px-4 rounded-xl focus:outline-none focus:shadow-outline w-full shadow-lg hover:shadow-amber-900/20 transition-all hover:scale-105 active:scale-95 duration-300" type="submit">
                                Sign In / Sign Up
                            </button>
                        </div>
                    </form>
                </div>
            </div>
        );
    }

    const renderSoundSection = (type: SoundType, title: string) => {
        let sectionSounds = sounds.filter(s => s.type === type);
        let filterUI = null;

        if (type === 'Background Music') {
            const moods = [...new Set(
                librarySounds
                    .filter(s => s.type === 'Background Music' && s.mood_tag)
                    .map(s => s.mood_tag!)
            )].sort();

            if (activeMoodFilter) {
                sectionSounds = sectionSounds.filter(s => s.mood_tag === activeMoodFilter);
            }

            if (moods.length > 0) {
                filterUI = (
                    <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm font-semibold text-stone-400">Mood:</span>
                         <button 
                            onClick={() => setActiveMoodFilter(null)} 
                            className={`px-3 py-1 text-xs rounded-full transition-colors ${!activeMoodFilter ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                        >
                            All
                        </button>
                        {moods.map(mood => (
                            <button 
                                key={mood} 
                                onClick={() => setActiveMoodFilter(mood)} 
                                className={`px-3 py-1 text-xs rounded-full transition-colors ${activeMoodFilter === mood ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                            >
                                {mood}
                            </button>
                        ))}
                    </div>
                );
            }
        } else if (type === 'One-shots') {
            const types = [...new Set(
                librarySounds
                    .filter(s => s.type === 'One-shots' && s.type_tag)
                    .flatMap(s => s.type_tag!.split(',').map(t => t.trim()).filter(Boolean))
            )].sort();

            if (activeSETypeFilter) {
                sectionSounds = sectionSounds.filter(s => 
                    s.type_tag?.split(',').map(t => t.trim()).includes(activeSETypeFilter)
                );
            }

            if (types.length > 0) {
                filterUI = (
                    <div className="flex items-center gap-2 flex-wrap mb-4">
                        <span className="text-sm font-semibold text-stone-400">Type:</span>
                        <button
                            onClick={() => setActiveSETypeFilter(null)}
                            className={`px-3 py-1 text-xs rounded-full transition-colors ${!activeSETypeFilter ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                        >
                            All
                        </button>
                        {types.map(sfxType => (
                            <button
                                key={sfxType}
                                onClick={() => setActiveSETypeFilter(sfxType)}
                                className={`px-3 py-1 text-xs rounded-full transition-colors ${activeSETypeFilter === sfxType ? 'bg-amber-600 text-white font-bold' : 'bg-stone-700 text-stone-300 hover:bg-stone-600'}`}
                            >
                                {sfxType}
                            </button>
                        ))}
                    </div>
                );
            }
        }

        const hasSoundsOfTypeInScene = sounds.some(s => s.type === type);

        if (!hasSoundsOfTypeInScene && !searchQuery) {
            return null;
        }

        if (searchQuery && sectionSounds.length === 0) {
            return null;
        }

        sectionSounds.sort((a, b) => {
            // 1. Favorites always first
            if (a.favorite !== b.favorite) {
                return a.favorite ? -1 : 1;
            }

            // 2. If we are in a Specific Scene view, prioritize scene-specific tiles (include_in_all_scenes = false)
            if (activeSceneId !== null) {
                if (a.include_in_all_scenes !== b.include_in_all_scenes) {
                    return a.include_in_all_scenes ? 1 : -1; // False comes before True
                }
            }

            // 3. Alphabetical
            return a.name.localeCompare(b.name);
        });

        return (
            <section className="mb-8">
                <h2 className="text-2xl font-medieval font-bold text-white mb-4">{title}</h2>
                {filterUI}
                <div className="grid grid-cols-3 sm:grid-cols-4 md:grid-cols-6 lg:grid-cols-8 gap-3 md:gap-4">
                    {sectionSounds.map(sound => (
                        <SoundTile 
                            key={sound.id} 
                            sound={sound}
                            isPlaying={!!playingStates[sound.id]}
                            onPlay={handlePlaySound}
                            onStop={handleStopSound}
                        />
                    ))}
                </div>
            </section>
        );
    }

    const isAnythingPlaying = Object.values(playingStates).some(p => p);
    const sortedLibrarySounds = [...librarySounds].sort((a, b) => a.name.localeCompare(b.name));

    return (
        <div className="min-h-screen bg-gradient-to-br from-stone-900 via-stone-800 to-stone-900 flex flex-col">
            <SceneHeader
                scenes={scenes}
                activeSceneId={activeSceneId}
                onSelectScene={handleSceneChange}
                isAudioContextPlaying={audioContextState === 'running'}
                onToggleGlobalPlayPause={handleToggleGlobalPlayPause}
                onStopAllSounds={handleStopAllSounds}
                bgmVolume={masterBGMVolume}
                onBgmVolumeChange={handleBGMVolumeChange}
                onLogout={handleLogout}
                onOpenSoundManager={() => setSoundManagerModalOpen(true)}
                onOpenSceneManager={() => setSceneManagerModalOpen(true)}
                airplayElement={soundManagerRef.current?.airPlayAudioElement || null}
                isPlayerVisible={isAnythingPlaying}
            />

            <main className="flex-grow p-4 md:p-8 pb-24">
                {renderSoundSection('Background Music', 'Background Music')}
                {renderSoundSection('Ambience', 'Ambience')}
                {renderSoundSection('One-shots', 'One-shots')}

                 {sounds.length === 0 && librarySounds.length > 0 && (
                    <div className="text-center text-stone-400 mt-10">
                        {searchQuery ? (
                             <p className="text-lg">No sounds match "{searchQuery}"</p>
                        ) : (
                            <>
                                <p className="text-lg">No sounds found in this scene.</p>
                                <p>Try selecting another scene or "All".</p>
                            </>
                        )}
                    </div>
                 )}
            </main>

            <AtmosphereFooter 
                activeAtmosphere={activeAtmosphere}
                onSelectAtmosphere={handleSelectAtmosphere}
                isSceneActive={!!activeSceneId || activeSceneId === null} // Always active now
            />

            <SearchWidget searchQuery={searchQuery} setSearchQuery={setSearchQuery} />

            <SoundManagerModal
                isOpen={isSoundManagerModalOpen}
                onClose={() => setSoundManagerModalOpen(false)}
                sounds={sortedLibrarySounds}
                allScenes={scenes}
                onAddSound={handleAddSound}
                onUpdateSound={handleUpdateSound}
                onDeleteSound={handleDeleteSound}
            />
            <SceneManagerModal
                isOpen={isSceneManagerModalOpen}
                onClose={() => setSceneManagerModalOpen(false)}
                scenes={scenes}
                sounds={sortedLibrarySounds}
                onAddScene={handleAddScene}
                onRemoveScene={handleRemoveScene}
                onUpdateSceneJoins={handleUpdateSceneJoins}
            />
        </div>
    );
};

export default App;

{
  "name": "Sound Forge",
  "description": "A web-based soundboard application for tabletop RPG game masters to manage and play ambient sounds, background music, and sound effects during gameplay sessions.",
  "requestFramePermissions": []
}

import React, { useState, useEffect, useRef } from 'react';
import { Scene, Sound, AtmosphereLevel } from '../types';
import { X, Plus, Trash2, Layers, AlertTriangle, Check, ArrowLeft, Search, Coffee, Shield, Zap, Globe, Play, StopCircle } from 'lucide-react';

interface SceneManagerModalProps {
  isOpen: boolean;
  onClose: () => void;
  scenes: Scene[];
  sounds: Sound[]; // Need all sounds to populate the editor
  onAddScene: (name: string) => Promise<void>;
  onRemoveScene: (id: string) => Promise<{ success: boolean; error?: string }>;
  onUpdateSceneJoins: (sceneId: string, soundData: Array<{ sound_id: string; atmosphere: AtmosphereLevel[] }>) => Promise<void>;
}

const atmosphereConfig: { [key in AtmosphereLevel]: { icon: React.ReactNode; colorClass: string; activeClass: string; } } = {
  'Relaxed': { icon: <Coffee size={14} />, colorClass: 'text-green-500', activeClass: 'bg-green-600 border-green-500 text-white shadow-green-900/40' },
  'Neutral': { icon: <Shield size={14} />, colorClass: 'text-sky-500', activeClass: 'bg-sky-600 border-sky-500 text-white shadow-sky-900/40' },
  'Intense': { icon: <Zap size={14} />, colorClass: 'text-red-500', activeClass: 'bg-red-600 border-red-500 text-white shadow-red-900/40' },
};

const AtmosphereEditor: React.FC<{
    scene: Scene;
    sounds: Sound[];
    onBack: () => void;
    onSave: (soundData: Array<{ sound_id: string; atmosphere: AtmosphereLevel[] }>) => Promise<void>;
}> = ({ scene, sounds, onBack, onSave }) => {
    const [searchQuery, setSearchQuery] = useState('');
    const [filter, setFilter] = useState<'All' | 'BGM' | 'Ambience'>('All');
    const [state, setState] = useState<Record<string, Set<AtmosphereLevel>>>({});
    const [isSaving, setIsSaving] = useState(false);

    // Preview State
    const [previewId, setPreviewId] = useState<string | null>(null);
    const audioRef = useRef<HTMLAudioElement | null>(null);

    // Initialize state based on current scene connections
    useEffect(() => {
        const initialState: Record<string, Set<AtmosphereLevel>> = {};
        sounds.forEach(sound => {
            if (sound.type === 'One-shots') return; // Skip one-shots for atmosphere

            const sceneInfo = sound.scenes?.find(s => s.id === scene.id);
            if (sceneInfo?.atmosphere && sceneInfo.atmosphere.length > 0) {
                initialState[sound.id] = new Set(sceneInfo.atmosphere);
            }
        });
        setState(initialState);
    }, [scene, sounds]);

    // Cleanup audio on unmount
    useEffect(() => {
        return () => {
            if (audioRef.current) {
                audioRef.current.pause();
                audioRef.current = null;
            }
        };
    }, []);

    const togglePreview = (sound: Sound) => {
        if (previewId === sound.id) {
            audioRef.current?.pause();
            audioRef.current = null;
            setPreviewId(null);
        } else {
            if (audioRef.current) {
                audioRef.current.pause();
            }
            if (sound.publicURL) {
                const audio = new Audio(sound.publicURL);
                audio.volume = Math.min(sound.volume, 1);
                audio.onended = () => setPreviewId(null);
                audio.play().catch(e => console.error("Preview error:", e));
                audioRef.current = audio;
                setPreviewId(sound.id);
            }
        }
    };

    const handleToggle = (soundId: string, level: AtmosphereLevel) => {
        setState(prev => {
            const next = { ...prev };
            const currentSet = next[soundId] ? new Set(next[soundId]) : new Set<AtmosphereLevel>();

            if (currentSet.has(level)) {
                currentSet.delete(level);
            } else {
                currentSet.add(level);
            }

            if (currentSet.size === 0) {
                delete next[soundId];
            } else {
                next[soundId] = currentSet;
            }
            return next;
        });
    };

    const handleSave = async () => {
        setIsSaving(true);
        if (audioRef.current) {
            audioRef.current.pause();
            audioRef.current = null;
            setPreviewId(null);
        }
        const payload = Object.entries(state).map(([soundId, set]) => ({
            sound_id: soundId,
            atmosphere: Array.from(set as Set<AtmosphereLevel>)
        }));
        await onSave(payload);
        setIsSaving(false);
        onBack();
    };

    const filteredSounds = sounds
        .filter(s => s.type !== 'One-shots')
        .filter(s => filter === 'All' || (filter === 'BGM' && s.type === 'Background Music') || (filter === 'Ambience' && s.type === 'Ambience'))
        .filter(s => s.name.toLowerCase().includes(searchQuery.toLowerCase()))
        .sort((a, b) => {
            // Sort by: Active in this scene -> Name
            const aActive = !!state[a.id];
            const bActive = !!state[b.id];
            if (aActive !== bActive) return aActive ? -1 : 1;
            return a.name.localeCompare(b.name);
        });

    return (
        <div className="flex flex-col flex-grow min-h-0">
            <div className="flex items-center gap-2 mb-4 pb-4 border-b border-stone-700/50">
                <button onClick={onBack} className="p-2 hover:bg-stone-700 rounded-full text-stone-400 hover:text-white transition-colors">
                    <ArrowLeft size={20} />
                </button>
                <div>
                    <h3 className="text-xl font-medieval font-bold text-white leading-none">Edit Atmosphere</h3>
                    <p className="text-stone-400 text-sm">Scene: <span className="text-amber-400">{scene.name}</span></p>
                </div>
            </div>

            <div className="flex gap-2 mb-4">
                <div className="relative flex-grow">
                    <Search className="absolute left-3 top-1/2 -translate-y-1/2 text-stone-500" size={16} />
                    <input 
                        type="text" 
                        value={searchQuery}
                        onChange={e => setSearchQuery(e.target.value)}
                        placeholder="Search sounds..."
                        className="w-full bg-stone-800/40 border border-stone-600/50 rounded-xl pl-9 pr-3 py-2 text-sm text-white focus:border-amber-500 outline-none transition-colors"
                    />
                </div>
                <select 
                    value={filter} 
                    onChange={e => setFilter(e.target.value as any)}
                    className="bg-stone-800/40 border border-stone-600/50 rounded-xl px-3 text-sm text-stone-300 focus:border-amber-500 outline-none"
                >
                    <option value="All">All Types</option>
                    <option value="BGM">Music</option>
                    <option value="Ambience">Ambience</option>
                </select>
            </div>

            {/* Adjusted grid to include Preview column */}
            <div className="grid grid-cols-[3rem_2fr_repeat(3,1fr)] gap-3 mb-2 px-2 text-xs font-bold text-stone-500 uppercase tracking-wider text-center items-center">
                <div>Preview</div>
                <div className="text-left">Sound</div>
                <div>Relaxed</div>
                <div>Neutral</div>
                <div>Intense</div>
            </div>

            <div className="flex-grow min-h-0 overflow-y-auto custom-scrollbar space-y-1 pr-1">
                {filteredSounds.map(sound => {
                    const activeLevels = state[sound.id] || new Set();
                    return (
                        <div key={sound.id} className={`grid grid-cols-[3rem_2fr_repeat(3,1fr)] gap-3 items-center p-2 rounded-lg border transition-colors ${activeLevels.size > 0 ? 'bg-stone-800/60 border-stone-700' : 'border-transparent hover:bg-stone-800/30'}`}>

                            <div className="flex justify-center">
                                <button 
                                    onClick={() => togglePreview(sound)}
                                    className={`p-2 rounded-full transition-colors ${previewId === sound.id ? 'text-amber-400 bg-stone-700' : 'text-stone-500 hover:text-amber-400 hover:bg-stone-700/50'}`}
                                    title={previewId === sound.id ? "Stop Preview" : "Play Preview"}
                                >
                                    {previewId === sound.id ? <StopCircle size={20} /> : <Play size={20} />}
                                </button>
                            </div>

                            <div className="min-w-0">
                                <p className="text-sm font-medium text-stone-200 truncate" title={sound.name}>{sound.name}</p>
                                <div className="flex items-center gap-1">
                                     <span className="text-[10px] text-stone-500 uppercase">{sound.type === 'Background Music' ? 'Music' : 'Ambience'}</span>
                                     {/* FIX: Removed title attribute from Globe component as it is not a valid prop for Lucide components */}
                                     {sound.include_in_all_scenes && <Globe size={10} className="text-sky-400/70" />}
                                </div>
                            </div>

                            {(['Relaxed', 'Neutral', 'Intense'] as AtmosphereLevel[]).map(level => {
                                const isActive = activeLevels.has(level);
                                const config = atmosphereConfig[level];
                                return (
                                    <div key={level} className="flex justify-center">
                                        <button
                                            onClick={() => handleToggle(sound.id, level)}
                                            className={`w-full max-w-[60px] h-8 rounded-md flex items-center justify-center transition-all border ${isActive ? config.activeClass : 'bg-stone-900/50 border-stone-700 text-stone-600 hover:border-stone-500 hover:text-stone-400'}`}
                                            title={`Toggle ${level} for ${sound.name}`}
                                        >
                                            {config.icon}
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    );
                })}
                {filteredSounds.length === 0 && <p className="text-center text-stone-500 py-8">No matching sounds found.</p>}
            </div>

            <div className="mt-4 flex justify-end pt-4 border-t border-stone-700/30">
                <button onClick={handleSave} disabled={isSaving} className="py-2 px-6 rounded-xl text-white bg-amber-600 hover:bg-amber-500 disabled:bg-stone-600 shadow-lg hover:shadow-amber-900/20 transition-all flex items-center gap-2">
                    {isSaving ? 'Saving...' : 'Save Changes'}
                </button>
            </div>
        </div>
    );
};

export const SceneManagerModal: React.FC<SceneManagerModalProps> = ({
  isOpen,
  onClose,
  scenes,
  sounds,
  onAddScene,
  onRemoveScene,
  onUpdateSceneJoins,
}) => {
  const [newSceneName, setNewSceneName] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [confirmDeleteId, setConfirmDeleteId] = useState<string | null>(null);
  const [editingScene, setEditingScene] = useState<Scene | null>(null);

  const [showModal, setShowModal] = useState(isOpen);

  useEffect(() => {
      if (isOpen) {
          setShowModal(true);
      } else {
          const timer = setTimeout(() => setShowModal(false), 100);
          return () => clearTimeout(timer);
      }
  }, [isOpen]);

  useEffect(() => {
      if (!isOpen) setEditingScene(null);
  }, [isOpen]);

  if (!showModal) return null;

  const handleAdd = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newSceneName.trim()) return;

    if (scenes.some(s => s.name.toLowerCase() === newSceneName.trim().toLowerCase())) {
        setError('A scene with this name already exists.');
        return;
    }

    setIsSubmitting(true);
    setError(null);
    await onAddScene(newSceneName);
    setNewSceneName('');
    setIsSubmitting(false);
  };

  const handleDeleteClick = (e: React.MouseEvent, id: string) => {
      e.stopPropagation();
      e.preventDefault();
      if (confirmDeleteId === id) {
          executeDelete(id);
      } else {
          setConfirmDeleteId(id);
      }
  };

  const executeDelete = async (id: string) => {
      setError(null);
      const result = await onRemoveScene(id);
      if (!result.success) {
          setError(result.error || "Failed to delete scene.");
      }
      setConfirmDeleteId(null);
  };

  const cancelDelete = (e: React.MouseEvent) => {
      e.stopPropagation();
      e.preventDefault();
      setConfirmDeleteId(null);
  };

  const handleClose = () => {
      setConfirmDeleteId(null);
      setError(null);
      setEditingScene(null);
      onClose();
  };

  return (
    <div className="fixed inset-0 z-50 flex items-center justify-center p-4">
      <div 
        className={`absolute inset-0 bg-stone-950/40 backdrop-blur-sm transition-opacity duration-300 ${isOpen ? 'opacity-100' : 'opacity-0'}`}
        onClick={handleClose}
      />

      <div 
        className={`relative bg-stone-900/60 backdrop-blur-2xl border border-stone-700/50 shadow-2xl rounded-3xl p-6 w-full m-4 h-[85vh] flex flex-col transition-all duration-300 ${editingScene ? 'max-w-4xl' : 'max-w-2xl'} ${isOpen ? 'animate-modal-in' : 'animate-modal-out'}`}
        onClick={() => setConfirmDeleteId(null)}
      >
        {!editingScene ? (
            // LIST VIEW
            <>
                <div className="flex justify-between items-center mb-6" onClick={e => e.stopPropagation()}>
                    <h2 className="text-2xl font-medieval font-bold text-white flex items-center gap-2 drop-shadow-sm">
                        <Layers className="text-amber-500" size={24} /> Manage Scenes
                    </h2>
                    <button onClick={handleClose} className="p-2 text-stone-400 hover:text-white hover:bg-stone-700/50 rounded-full transition-colors">
                        <X size={24} />
                    </button>
                </div>

                <form onSubmit={handleAdd} className="mb-6" onClick={e => e.stopPropagation()}>
                    <div className="flex gap-2">
                        <input 
                            type="text" 
                            value={newSceneName}
                            onChange={(e) => setNewSceneName(e.target.value)}
                            placeholder="New Scene Name"
                            className="flex-1 bg-stone-800/40 border border-stone-600/50 rounded-xl p-3 text-white placeholder-stone-500 focus:border-amber-500 focus:ring-1 focus:ring-amber-500 outline-none transition-all"
                        />
                        <button 
                            type="submit" 
                            disabled={isSubmitting || !newSceneName.trim()}
                            className="bg-amber-600 hover:bg-amber-500 text-white p-3 rounded-xl disabled:bg-stone-700 disabled:text-stone-500 transition-all shadow-lg hover:shadow-amber-900/20"
                        >
                            <Plus size={20} />
                        </button>
                    </div>
                    {error && (
                    <div className="flex items-center gap-2 text-red-400 text-sm mt-3 bg-red-900/20 p-3 rounded-lg border border-red-800/50 animate-pulse">
                        <AlertTriangle size={16} />
                        {error}
                    </div>
                    )}
                </form>

                <div className="flex-grow min-h-0 overflow-y-auto bg-stone-900/30 rounded-xl border border-stone-700/30 p-2 custom-scrollbar" onClick={e => e.stopPropagation()}>
                    {scenes.length === 0 ? (
                        <p className="text-stone-500 text-center py-8 italic">No scenes created yet.</p>
                    ) : (
                        <ul className="space-y-2">
                            {scenes.map(scene => {
                                const isConfirming = confirmDeleteId === scene.id;
                                return (
                                    <li 
                                        key={scene.id} 
                                        className={`flex justify-between items-center p-3 rounded-lg transition-all duration-200 border ${isConfirming ? 'bg-red-900/10 border-red-900/30' : 'bg-stone-800/50 border-transparent hover:bg-stone-700/50 hover:border-stone-600/50'}`}
                                    >
                                        <div className="flex items-center gap-3 overflow-hidden">
                                            <span className={`font-medium truncate transition-colors ${isConfirming ? 'text-red-200' : 'text-stone-200'}`}>
                                                {scene.name}
                                            </span>
